// hw/hls/mel_frontend.cpp — sketch; fill in using UG1399 + the hls::fft example.
// Must follow Vad.update() in common/features.py step for step (same order of operations).
#include "ap_axi_sdata.h"
#include "hls_stream.h"
#include "hls_math.h"
#include "hls_fft.h"
#include "mel_fb.h"   // generated by features.py: HANN, MEL_W, VAD_LO, VAD_HI, NF_DOWN, NF_UP,
                      // NF_WARM, VAD_WARMUP, VAD_STUCK_FRAMES, VAD_STUCK_WINDOWS, EPS

typedef ap_axiu<32,0,0,0> pkt;               // 32-bit AXI-Stream word with TLAST

void mel_frontend(hls::stream<pkt>& in, hls::stream<pkt>& out,
                  int n_frames,                // in : 49
                  float margin,                // in : VAD margin in nepers (9 dB = 2.0723)
                  int min_frames,              // in : 5
                  int hang,                    // in : 1
                  int reset,                   // in : 1 = forget the noise floor (warm up again)
                  int* gate,                   // out: 1 = gate open for this window
                  int* n_speech,               // out: speech frames in this window
                  float* noise_floor) {        // out: ln(energy) of the floor, for the heartbeat
#pragma HLS INTERFACE axis port=in
#pragma HLS INTERFACE axis port=out
#pragma HLS INTERFACE s_axilite port=n_frames
#pragma HLS INTERFACE s_axilite port=margin
#pragma HLS INTERFACE s_axilite port=min_frames
#pragma HLS INTERFACE s_axilite port=hang
#pragma HLS INTERFACE s_axilite port=reset
#pragma HLS INTERFACE s_axilite port=gate
#pragma HLS INTERFACE s_axilite port=n_speech
#pragma HLS INTERFACE s_axilite port=noise_floor
#pragma HLS INTERFACE s_axilite port=return
    // 'static' = state that survives between calls. This IS the always-on part:
    // the floor keeps tracking the room across windows without the ARM remembering anything.
    static float nf = 0.0f;
    static int seen = 0, hold = 0, stuck = 0;
    if (reset) { seen = 0; hold = 0; stuck = 0; }

    int ns = 0; float low = 1e30f;
    for (int f = 0; f < n_frames; f++) {
        // 1. read 512 samples (low 16 bits of each word), multiply by HANN[i]
        // 2. hls::fft 512-pt forward   3. power[k] = re*re + im*im, k = 0..256
        // 4. mel[m] = sum_k MEL_W[m][k] * power[k], m = 0..39
        // 5. write 40 float words; TLAST only on the very last word of the last frame
        // 6. VAD for this frame:
        float s = 0; for (int m = VAD_LO; m < VAD_HI; m++) s += mel[m];
        float e = hls::logf(s + EPS);
        if (seen == 0) nf = e;
        if (seen < VAD_WARMUP) { seen++; nf += (e - nf) * NF_WARM; continue; }  // warm-up
        if (e > nf + margin) ns++;
        nf += (e - nf) * (e < nf ? NF_DOWN : NF_UP);   // fall fast, rise slowly
        if (e < low) low = e;
    }
    stuck = (ns >= VAD_STUCK_FRAMES) ? stuck + 1 : 0;   // ~2 s non-stop loud = new background
    if (stuck >= VAD_STUCK_WINDOWS) { nf = low; stuck = 0; ns = 0; }
    if (ns >= min_frames) hold = hang + 1;
    *gate = (hold > 0); if (hold > 0) hold--;
    *n_speech = ns; *noise_floor = nf;
}
